using UnlimitedPDF.Demos.BlazorWasm.Samples.Inputs;
using UnlimitedPDF;

namespace UnlimitedPDF.Demos.BlazorWasm.Samples;

/// <summary>
/// Builds a merge pack: a cover page listing the documents, then each included document under a bookmark named after
/// it. The documents are generated by the other demos and loaded back as existing PDFs.
/// </summary>
public static class MergePackSample
{
    #region Methods

    #region Public Methods

    /// <summary>
    /// Builds the pack.
    /// </summary>
    /// <param name="input">The cover title and the documents.</param>
    /// <returns>The document, ready to save.</returns>
    /// <exception cref="InvalidOperationException">No document is included.</exception>
    public static PdfDocument Build(MergePackInput input)
    {
        var included = input.Documents.Where(document => document.Include && document.File is not null).ToList();
        if (included.Count == 0) throw new InvalidOperationException("Choose at least one document.");

        var pack = new PdfDocument();
        pack.Footer.Height = 30;
        pack.Footer.AddText("{pages} pages", 0, 10, 10, PdfTextAlignment.Center);

        var cover = pack.AddPage();
        cover.AddText(input.CoverTitle, 72, 720, 26);
        cover.AddText("Contents", 72, 680, 14);
        int line = 655;
        foreach (var document in included)
        {
            cover.AddText($"{document.Name} ({document.File!.PageCount} {(document.File.PageCount == 1 ? "page" : "pages")})", 90, line, 12);
            line -= 20;
        }

        foreach (var document in included)
            pack.AddPages(document.File!, bookmarkTitle: document.Name);
        return pack;
    }

    #endregion

    #endregion
}
